function getDomain(url) {
  try {
    const match = (url || '').match(/https?:\/\/([^\/]+)/);
    return match ? match[1].replace('www.', '') : 'unknown';
  } catch {
    return 'unknown';
  }
}

const items = $input.all();
const now = new Date();
const cutoff24h = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const erroredFeeds = items.filter((item) => item.json?.error);
const today = now.toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
});
const episodeSlug = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');

const buildResult = ({
  systemPrompt = '',
  userMessage = '',
  articleCount = 0,
  selectedArticles = [],
  showNotes = '',
  noStoriesReason = '',
} = {}) => ([
  {
    json: {
      systemPrompt,
      userMessage,
      date: today,
      episodeSlug,
      articleCount,
      selectedArticles,
      showNotes,
      feedErrorCount: erroredFeeds.length,
      noStoriesReason,
    },
  },
]);

const articles = items
  .filter((item) => item.json.title && !item.json.error)
  .map((item) => ({
    title: item.json.title || '',
    link: item.json.link || '',
    snippet: (item.json.contentSnippet || '').substring(0, 300),
    pubDate: item.json.isoDate || item.json.pubDate || '',
    source: getDomain(item.json.link),
  }));

if (items.length > 0 && erroredFeeds.length === items.length) {
  throw new Error('All RSS feeds failed');
}

if (articles.length === 0) {
  const noStoriesReason = erroredFeeds.length
    ? `No articles returned. ${erroredFeeds.length} feed(s) failed during fetch.`
    : 'No articles returned from feeds.';
  return buildResult({ noStoriesReason });
}

const recent = articles.filter((article) => {
  if (!article.pubDate) return false;
  const parsed = new Date(article.pubDate);
  return !Number.isNaN(parsed.getTime()) && parsed >= cutoff24h;
});

if (recent.length === 0) {
  const noStoriesReason = erroredFeeds.length
    ? `No fresh stories in last 24 hours. ${erroredFeeds.length} feed(s) failed during fetch.`
    : 'No fresh stories in last 24 hours.';
  return buildResult({ noStoriesReason });
}

const seen = new Set();
const unique = recent.filter((article) => {
  const key = article.title.toLowerCase().replace(/[^a-z0-9]/g, '').substring(0, 50);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

const sorted = unique.sort((a, b) => new Date(b.pubDate || 0) - new Date(a.pubDate || 0));

const counts = {};
const diverse = sorted
  .filter((article) => {
    counts[article.source] = (counts[article.source] || 0) + 1;
    return counts[article.source] <= 2;
  })
  .slice(0, 8);

const selectedArticles = diverse.map((article, index) => ({
  rank: index + 1,
  title: article.title,
  link: article.link,
  source: article.source,
  snippet: article.snippet,
}));

const articlesText = selectedArticles
  .map((article) =>
    `${article.rank}. ${article.title} (${article.source})\n${article.snippet}\nURL: ${article.link}`,
  )
  .join('\n\n');

const showNotes = selectedArticles
  .map((article) => `${article.rank}. ${article.title} (${article.source})\n${article.link}`)
  .join('\n');

const systemPrompt = `You are the host of "AI Digest Daily", a daily podcast for software engineers and AI enthusiasts.

Editorial focus:
- Prioritize stories with real engineering impact: models, APIs, SDKs, dev tools, benchmarks, open-source releases, infra, security, and practical workflows.
- De-prioritize generic hype, funding drama, and vague predictions unless there is a concrete builder takeaway.

Style rules:
- Conversational but informed, like a senior engineer giving a crisp daily briefing.
- Cover 4-6 strongest stories.
- 30-60 seconds per story.
- Use smooth transitions between stories.
- Keep sentences short and spoken-word friendly for TTS.
- No markdown, no stage directions, no bullet formatting.

For each story, include:
- What happened (1-2 sentences)
- Why it matters to software engineers and AI enthusiasts
- One concrete next action: what to test, ship, or read next

Output constraints:
- Start with "Welcome to AI Digest Daily for ${today}"
- End with "That's your AI digest for today. Stay curious."
- Mention story numbers naturally ("story one", "story two") so listeners can map to show notes links.
- Total 600-800 words
- Stay under 3500 characters
- Pure spoken text only`;

const userMessage = `Here are today's AI stories with source URLs for citation:

${articlesText}

Write the podcast script now.`;

return buildResult({
  systemPrompt,
  userMessage,
  articleCount: selectedArticles.length,
  selectedArticles,
  showNotes,
});

const input = $input.first().json;
let script = '';
if (input.choices) {
  script = input.choices[0].message.content || '';
} else {
  script = input.text || input.content || '';
}

if (!script) {
  throw new Error('No script text generated');
}

// Safety: truncate at sentence boundary if over 4000 chars
if (script.length > 4000) {
  const truncated = script.substring(0, 4000);
  const lastPeriod = truncated.lastIndexOf('.');
  if (lastPeriod > 3000) {
    script = truncated.substring(0, lastPeriod + 1);
  } else {
    script = truncated;
  }
  script += " That's your AI digest for today. Stay curious.";
}

return [{ json: { text: script } }];

const date = new Date().toISOString().split('T')[0];
const fallbackSlug = new Date().toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
let episodeSlug = fallbackSlug;
try {
  episodeSlug = $('Build Script Prompt').first().json.episodeSlug || fallbackSlug;
} catch {}

const filename = `episodes/ai-digest-${episodeSlug}.mp3`;
const publicUrl = `https://pub-9b797e802d6047af9f356783bf25a650.r2.dev/${filename}`;
const feedUrl = 'https://pub-9b797e802d6047af9f356783bf25a650.r2.dev/podcast.xml';

let articleCount = 0;
try {
  articleCount = $('Build Script Prompt').first().json.articleCount;
} catch {}

let feedErrorCount = 0;
try {
  feedErrorCount = $('Build Script Prompt').first().json.feedErrorCount || 0;
} catch {}

const feedWarning = feedErrorCount > 0 ? `\nRSS issues: ${feedErrorCount} feed(s) failed this run` : '';

const content = `AI Digest Daily - ${date}\n\nListen: ${publicUrl}\nRSS Feed: ${feedUrl}\n\nGenerated from ${articleCount} articles${feedWarning}\nNew episode is live.`;

return [{ json: { content } }];

const r2Base = 'https://pub-9b797e802d6047af9f356783bf25a650.r2.dev';
const feedUrl = `${r2Base}/podcast.xml`;
const siteUrl = feedUrl;
const coverUrl = `${r2Base}/podcast-cover.jpg`;
const ownerEmail = 'digest@bhekani.com';
const ownerName = 'AI Digest';
const now = new Date();
const episodeSlugFallback = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z');
let episodeSlug = episodeSlugFallback;
try {
  episodeSlug = $('Build Script Prompt').first().json.episodeSlug || episodeSlugFallback;
} catch {}

const audioUrl = `${r2Base}/episodes/ai-digest-${episodeSlug}.mp3`;

let script = '';
try {
  script = $('Trim Script').first().json.text || '';
} catch {}

let articleCount = 0;
try {
  articleCount = $('Build Script Prompt').first().json.articleCount || 0;
} catch {}

let selectedArticles = [];
try {
  selectedArticles = $('Build Script Prompt').first().json.selectedArticles || [];
} catch {}

const escapeXml = (value = '') =>
  String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&apos;');

const audioHead = await fetch(`${audioUrl}?t=${Date.now()}`, { method: 'HEAD' });
if (!audioHead.ok) {
  throw new Error(`Audio URL not reachable for enclosure: ${audioHead.status}`);
}

const audioBytes = Number(audioHead.headers.get('content-length') || '0');
if (!Number.isFinite(audioBytes) || audioBytes <= 0) {
  throw new Error('Unable to determine audio file size for enclosure');
}

const titleDate = now.toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  timeZone: 'UTC',
});
const titleTime = now.toLocaleTimeString('en-GB', {
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  timeZone: 'UTC',
});
const episodeTitle = `AI Digest Daily - ${titleDate} ${titleTime} UTC`;
const guid = `ai-digest-${episodeSlug}`;

const showNotesText = selectedArticles.length
  ? selectedArticles.map((article) => `${article.rank}. ${article.title} (${article.source})\n${article.link}`).join('\n')
  : `No links captured for this episode. Feed: ${feedUrl}`;

const transcriptAndNotes = script
  ? `${script}\n\nShow Notes and Links:\n${showNotesText}`
  : `Show Notes and Links:\n${showNotesText}`;

const episodeDescription = transcriptAndNotes.substring(0, 8000);
const channelSummary = `Daily AI digest for software engineers and AI enthusiasts. ${articleCount} source stories in this episode.`;

const newItemXml = [
  '    <item>',
  `      <title>${escapeXml(episodeTitle)}</title>`,
  `      <description>${escapeXml(episodeDescription)}</description>`,
  `      <pubDate>${now.toUTCString()}</pubDate>`,
  `      <guid isPermaLink="false">${guid}</guid>`,
  `      <link>${audioUrl}</link>`,
  '      <itunes:episodeType>full</itunes:episodeType>',
  `      <enclosure url="${audioUrl}" length="${audioBytes}" type="audio/mpeg"/>`,
  '    </item>',
].join('\n');

let existingItems = [];
const existingFeedResponse = await fetch(`${feedUrl}?t=${Date.now()}`, {
  method: 'GET',
  headers: {
    'Cache-Control': 'no-cache',
  },
});

if (existingFeedResponse.status === 404) {
  existingItems = [];
} else if (!existingFeedResponse.ok) {
  throw new Error(`Unable to fetch existing podcast feed: ${existingFeedResponse.status}`);
} else {
  const existingXml = await existingFeedResponse.text();
  existingItems = existingXml.match(/<item>[\s\S]*?<\/item>/g) || [];
}

const extractGuid = (itemXml = '') => {
  const match = itemXml.match(/<guid[^>]*>([\s\S]*?)<\/guid>/i);
  return match ? match[1].trim() : '';
};

const seenGuids = new Set([guid]);
const mergedItems = [newItemXml];
for (const itemXml of existingItems) {
  const existingGuid = extractGuid(itemXml);
  if (existingGuid && seenGuids.has(existingGuid)) continue;
  if (existingGuid) seenGuids.add(existingGuid);
  mergedItems.push(itemXml);
}

const maxEpisodes = 30;
const itemsXml = mergedItems.slice(0, maxEpisodes).join('\n');

const xml = [
  '<?xml version="1.0" encoding="UTF-8"?>',
  '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom" xmlns:itunes="http://www.itunes.com/dtds/podcast-1.0.dtd">',
  '  <channel>',
  '    <title>AI Digest Daily</title>',
  `    <link>${siteUrl}</link>`,
  `    <atom:link href="${feedUrl}" rel="self" type="application/rss+xml"/>`,
  '    <description>Daily AI digest in podcast form for software engineers and AI enthusiasts.</description>',
  '    <language>en-us</language>',
  `    <copyright>${new Date().getUTCFullYear()} AI Digest</copyright>`,
  `    <lastBuildDate>${now.toUTCString()}</lastBuildDate>`,
  '    <itunes:author>AI Digest</itunes:author>',
  `    <itunes:summary>${escapeXml(channelSummary)}</itunes:summary>`,
  '    <itunes:explicit>false</itunes:explicit>',
  '    <itunes:type>episodic</itunes:type>',
  '    <itunes:category text="Technology"/>',
  '    <itunes:owner>',
  `      <itunes:name>${escapeXml(ownerName)}</itunes:name>`,
  `      <itunes:email>${escapeXml(ownerEmail)}</itunes:email>`,
  '    </itunes:owner>',
  `    <itunes:image href="${coverUrl}"/>`,
  '    <image>',
  `      <url>${coverUrl}</url>`,
  '      <title>AI Digest Daily</title>',
  `      <link>${siteUrl}</link>`,
  '    </image>',
  itemsXml,
  '  </channel>',
  '</rss>',
].join('\n');

return [{
  json: { feedUrl, audioUrl, articleCount, episodeSlug, itemCount: mergedItems.length },
  binary: {
    data: {
      data: Buffer.from(xml, 'utf8').toString('base64'),
      mimeType: 'application/rss+xml',
      fileName: 'podcast.xml',
    },
  },
}];

const coverUrl = 'https://pub-9b797e802d6047af9f356783bf25a650.r2.dev/podcast-cover.jpg';
return [{
  json: { coverUrl },
  binary: {
    data: {
      data: '',
      mimeType: 'image/jpeg',
      fileName: 'podcast-cover.jpg',
    },
  },
}];

const date = new Date().toISOString().split('T')[0];
const feedErrorCount = $input.first().json.feedErrorCount || 0;
const noStoriesReason = $input.first().json.noStoriesReason || 'No fresh stories in last 24 hours.';
const content = `AI Digest Daily - ${date}\n\nNo episode published today.\n${noStoriesReason}\nCheck the feed sources in n8n. RSS issues: ${feedErrorCount} feed(s) failed this run.`;

return [{ json: { content } }];
